<script setup lang="ts">
import{ref,onMounted,onBeforeUnmount,watch}from'vue';import type{Task}from'../../../packages/contracts';import{changeTask}from'../../../packages/storage';import{taskPreviewSource}from'./task-files';import{videoFrames}from'./video-frames';import Icon from'./Icon.vue';
const props=defineProps<{task:Task}>(),image=ref(props.task.thumbnail),host=ref<HTMLElement>();let observer:IntersectionObserver|undefined;const abort=new AbortController();
function schedule(){if(!host.value||image.value||!(props.task.saved||props.task.output)||abort.signal.aborted)return;observer?.disconnect();observer=new IntersectionObserver(entries=>{if(!entries.some(e=>e.isIntersecting))return;observer?.disconnect();void navigator.locks.request('alcydeo:thumbnail',async()=>{if(abort.signal.aborted)return;if(props.task.thumbnail){image.value=props.task.thumbnail;return;}try{const time=.1+crypto.getRandomValues(new Uint32Array(1))[0]!/2**32*.8,source=await taskPreviewSource(props.task),frames=await videoFrames(source,[time],abort.signal);if(abort.signal.aborted)return;image.value=frames.images[0];await changeTask(props.task.id,t=>{t.thumbnail=frames.images[0];t.thumbnailTime=time*frames.duration;});}catch{/* A missing file/unsupported codec keeps a neutral media icon. */}});});observer.observe(host.value);}
watch(()=>[props.task.saved,props.task.output,props.task.thumbnail],schedule);const added=(permission:chrome.permissions.Permissions)=>{if(permission.origins?.some(origin=>origin.startsWith('file:')))schedule();};
onMounted(()=>{chrome.permissions.onAdded.addListener(added);schedule();});onBeforeUnmount(()=>{chrome.permissions.onAdded.removeListener(added);observer?.disconnect();abort.abort();});
</script>
<template><span ref="host" class="task-thumbnail"><img v-if="image" :src="image" alt="" loading="lazy"><Icon v-else :name="task.recording ? 'record' : 'movie'" /></span></template>
<style scoped>.task-thumbnail{width:88px;height:54px;border-radius:10px;overflow:hidden;display:grid;place-items:center;flex-shrink:0;background:var(--subtle);color:var(--muted)}.task-thumbnail img{width:100%;height:100%;object-fit:cover}.task-thumbnail svg{width:24px;height:24px}@media(max-width:640px){.task-thumbnail{width:58px;height:40px}}</style>
